import {
  Component,
  ChangeDetectionStrategy,
  Input,
  OnChanges,
  SimpleChanges,
  ViewChildren,
  QueryList,
  ViewChild,
  ElementRef
} from '@angular/core';
import { AnimateDirective } from '@honoregaming/ui';

@Component({
  selector: 'hg-winner-probable-odds',
  templateUrl: './winner-probable-odds.component.html',
  styleUrls: ['./winner-probable-odds.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class WinnerProbableOddsComponent implements OnChanges {
  @Input()
  odd;

  @ViewChild('oddsElt')
  oddsElt: ElementRef;

  @ViewChildren(AnimateDirective)
  oddRef: QueryList<AnimateDirective>;

  constructor() {}

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['odd'] && !changes['odd'].firstChange) {
      const previousOdds = changes['odd'].previousValue;
      const currentOdds = changes['odd'].currentValue;
      if (currentOdds > previousOdds) {
        this.oddsElt.nativeElement.classList.remove('up', 'down');
        this.oddRef.forEach(x => x.animate('up'));
      } else if (currentOdds < previousOdds) {
        this.oddsElt.nativeElement.classList.remove('up', 'down');
        this.oddRef.forEach(x => x.animate('down'));
      }
    }
  }
}
