import { Component, ChangeDetectionStrategy, Input, OnChanges } from '@angular/core';
import { HorseRacingRaceCategoryType } from '@honoregaming/types';

@Component({
  selector: 'hg-horseracing-racetypes-icons',
  templateUrl: './horseracing-racetypes-icons.component.html',
  styleUrls: ['./horseracing-racetypes-icons.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class HorseracingRacetypesIconsComponent implements OnChanges {
  @Input()
  types: HorseRacingRaceCategoryType[];

  distinctedTypes: HorseRacingRaceCategoryType[];

  ngOnChanges(): void {
    if (this.types) {
      const temp = {};
      for (let i = 0; i < this.types.length; i++) {
        temp[this.types[i]] = undefined;
      }

      this.distinctedTypes = <HorseRacingRaceCategoryType[]>Object.keys(temp);
    }
  }
}
