import { Component, ChangeDetectionStrategy, OnInit, Inject, ChangeDetectorRef, OnDestroy } from '@angular/core';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { DestroySubject, startOfDayInOperatorTimeZone } from '@honoregaming/core';
import { EventsService } from '@honoregaming/events';
import { HorseRaceResultWithMeeting } from '@honoregaming/types';
import { finalize, takeUntil } from 'rxjs/operators';

@Component({
  selector: 'hg-horseracing-races-results',
  templateUrl: './races-results.component.html',
  styleUrls: ['./races-results.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class RacesResultsComponent extends DestroySubject implements OnInit, OnDestroy {
  isLoading = false;

  racesPerMeetings: HorseRaceResultWithMeeting[];

  daysOfResults: number = 3;
  days: Date[] = [];
  selectedDate: Date;

  activeMeetingNumber: number;

  constructor(
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration,
    private eventsService: EventsService,
    private cdRef: ChangeDetectorRef
  ) {
    super();
  }

  ngOnInit() {
    if (this.operatorConfiguration?.horseRacesResultsConfiguration?.horseRacesResults?.daysOfResults) {
      this.daysOfResults = this.operatorConfiguration.horseRacesResultsConfiguration.horseRacesResults.daysOfResults;
    }
    this.setDatePicker();
  }

  loadResults() {
    this.isLoading = true;
    this.activeMeetingNumber = undefined;
    this.eventsService
      .getAllHorseRacesResults(this.selectedDate)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.isLoading = false;
          this.cdRef.markForCheck();
          this.cdRef.detectChanges();
        })
      )
      .subscribe(races => {
        this.racesPerMeetings = races;
      });
  }

  toggleMeeting(meetingNumber) {
    this.activeMeetingNumber = meetingNumber === this.activeMeetingNumber ? null : meetingNumber;
  }

  setDatePicker() {
    const today = startOfDayInOperatorTimeZone(this.operatorConfiguration.timeZone);
    this.days[0] = today;
    for (let i = 1; i < this.daysOfResults; i++) {
      let nextDate = startOfDayInOperatorTimeZone(this.operatorConfiguration.timeZone);
      nextDate.setDate(this.days[0].getDate() - i);
      this.days[i] = nextDate;
    }
    if (!this.selectedDate) {
      this.selectedDate = this.days[0];
    }
  }
}
