import {
  Component,
  ChangeDetectionStrategy,
  Input,
  KeyValueDiffer,
  KeyValueDiffers,
  DoCheck,
  KeyValueChangeRecord,
  ChangeDetectorRef
} from '@angular/core';
import { Router } from '@angular/router';
import {
  EventWithEventBetTypes,
  HorseRace,
  HorseRaceEventBetType,
  HorseRaceMeeting,
  HorseRaceStateType,
  HorseRacingFormulationBetStateType,
  HorseRacingRaceCategoryType
} from '@honoregaming/types';

@Component({
  selector: 'hg-horseracing-race-card',
  templateUrl: './race-card.component.html',
  styleUrls: ['./race-card.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class RaceCardComponent implements DoCheck {
  @Input()
  set race(r: EventWithEventBetTypes<HorseRace, HorseRaceEventBetType>) {
    this._race = r;
    // Cree un differ pour les propriétés de la course
    this._KVDifferRace = this.differs?.find(r).create();
  }
  get race(): EventWithEventBetTypes<HorseRace, HorseRaceEventBetType> {
    return this._race;
  }
  _race: EventWithEventBetTypes<HorseRace, HorseRaceEventBetType>;
  _KVDifferRace: KeyValueDiffer<string, any>;

  @Input()
  isGoingLive: boolean;

  @Input()
  meeting: HorseRaceMeeting;

  quintePlus: { exists: boolean; booster: boolean } = { exists: false, booster: false };
  HorseRaceStateType = HorseRaceStateType;
  HorseRacingFormulationBetStateType = HorseRacingFormulationBetStateType;
  HorseRacingRaceCategoryType = HorseRacingRaceCategoryType;

  constructor(private cdRef: ChangeDetectorRef, private router: Router, private differs: KeyValueDiffers) {}

  goToRace(mettingNumber: number, raceNumber: number, formulationBetTypeId?: number) {
    this.router.navigate(['/horseracing/race', 'R' + mettingNumber + 'C' + raceNumber], {
      queryParams: { betTypeId: formulationBetTypeId }
    });
  }

  ngDoCheck() {
    const quintePlusEventBetType = this.race.eventBetTypes.find(
      f => f.betTypeId === 14 && f.betState === HorseRacingFormulationBetStateType.InSale
    );

    this.quintePlus = {
      exists: quintePlusEventBetType != null,
      booster: quintePlusEventBetType?.booster
    };

    if (this._KVDifferRace) {
      const raceChange = this._KVDifferRace.diff(this.race);
      if (raceChange) {
        raceChange.forEachChangedItem((record: KeyValueChangeRecord<string, any>) => {
          this.race[record.key] = record.currentValue;
          this.cdRef.markForCheck();
        });
      }

      this.cdRef.markForCheck();
    }
  }
}
