import { Directive, ViewContainerRef, Input, OnInit, ElementRef } from '@angular/core';
import { PopoverComponent } from '../components/popover/popover.component';
import { Overlay, ConnectionPositionPair } from '@angular/cdk/overlay';
import { TemplatePortal } from '@angular/cdk/portal';

@Directive({
  selector: '[hgPopoverAnchor]'
})
export class PopoverAnchorDirective implements OnInit {
  @Input('hgPopoverAnchor')
  popover: PopoverComponent;

  constructor(private viewContainerRef: ViewContainerRef, private elementRef: ElementRef, private overlay: Overlay) {}

  ngOnInit(): void {
    const portal = new TemplatePortal(this.popover.templateRef, this.viewContainerRef);
    const strategy = this.overlay
      .position()
      .flexibleConnectedTo(this.elementRef)
      .withFlexibleDimensions(false)
      .withPush(false)
      .withViewportMargin(10)
      .withLockedPosition(false)
      .withPositions([
        {
          originX: 'center',
          originY: 'bottom',
          overlayX: 'center',
          overlayY: 'top'
        },
        {
          originX: 'center',
          originY: 'top',
          overlayX: 'center',
          overlayY: 'bottom'
        },
        {
          originX: 'start',
          originY: 'center',
          overlayX: 'end',
          overlayY: 'center'
        },
        {
          originX: 'end',
          originY: 'center',
          overlayX: 'start',
          overlayY: 'center'
        }
      ]);

    const posToOrientation = (pos: ConnectionPositionPair) => {
      if (pos.originY !== 'center') {
        return pos.originY;
      } else {
        return pos.originX === 'start' ? 'left' : 'right';
      }
    };
    strategy.positionChanges.subscribe(pos => {
      this.popover.orientation = posToOrientation(pos.connectionPair);
    });

    this.overlay.scrollStrategies.close();

    const overlayRef = this.overlay.create({
      positionStrategy: strategy
    });

    this.popover.overlayRef = overlayRef;
    this.popover.portal = portal;
  }
}
