import { Component, ChangeDetectionStrategy, Input, OnChanges, SimpleChanges } from '@angular/core';
import { HorseRaceRunner } from '@honoregaming/types';

@Component({
  selector: 'hg-horseracing-runners-arrival',
  templateUrl: './runners-arrival.component.html',
  styleUrls: ['./runners-arrival.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class RunnersArrivalComponent implements OnChanges {
  @Input()
  runners: HorseRaceRunner[];
  orderedRunners: (HorseRaceRunner & { index?: number })[];

  ngOnChanges(_changes: SimpleChanges): void {
    this.orderedRunners = this.runners.sort((r1, r2) => {
      if (r2.arrivalPosition === r1.arrivalPosition) {
        return r1.number - r2.number;
      }

      return (
        (r1.arrivalPosition ? r1.arrivalPosition : Number.MAX_SAFE_INTEGER) -
        (r2.arrivalPosition ? r2.arrivalPosition : Number.MAX_SAFE_INTEGER)
      );
    });
  }
}
