import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  ViewChild,
  OnDestroy,
  PLATFORM_ID,
  Inject,
  NgZone,
  Optional
} from '@angular/core';
import { ActivatedRoute, Params, Router } from '@angular/router';
import { HttpErrorResponse } from '@angular/common/http';
import { finalize, takeUntil, map, skip } from 'rxjs/operators';
import { getUtcNow, delayBetween, happenBefore, IContainer } from '@honoregaming/customer-core';
import { RunnersSelectionComponent } from '../../components/runners-selection/runners-selection.component';
import { environment } from '../../../../../customer/src/environments/environment';
import { combineLatest, merge, Observable, Subject } from 'rxjs';
import { isPlatformBrowser } from '@angular/common';
import { RunnersSelection } from '../../models/runners-selection.model';
import {
  DestroySubject,
  PushService,
  DialogService,
  horseRaceBetTypesConfiguration,
  getDateInBrowserTimeZone
} from '@honoregaming/core';
import {
  HorseRacingFormulaKeyType,
  Formula,
  HorseRaceStateType,
  EventWithEventBetTypes,
  HorseRaceEventBetType,
  HorseRace,
  HorseRaceRunner,
  HorseRaceMeeting,
  HorseRacingFormulationBetStateType,
  HorseRacingRaceCategoryType
} from '@honoregaming/types';
import { EventsService } from '@honoregaming/events';
import { BetLine, BetLineChangeReason, BetSlipService, createHorseRaceBetLine, setSpot } from '@honoregaming/betslip';
import { Media, MediaService, MessageService } from '@honoregaming/ui';
import { PopinBettypesInformationsComponent } from '../../components/popin-bettypes-informations/popin-bettypes-informations.component';
import { PopinRaceConditionsComponent } from '../../components/popin-race-conditions/popin-race-conditions.component';

@Component({
  selector: 'hg-horseracing-race-detail',
  templateUrl: './race-detail.component.html',
  styleUrls: ['./race-detail.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class RaceDetailComponent extends DestroySubject implements OnInit, OnDestroy, IContainer {
  @ViewChild(RunnersSelectionComponent)
  runnerSelection: RunnersSelectionComponent;

  currentRace: EventWithEventBetTypes<HorseRace, HorseRaceEventBetType> & {
    isGoingLive: boolean;
    activeRunnersCount: number;
  };
  currentEventBetType: HorseRaceEventBetType;

  racesPerMeetings: {
    meeting: HorseRaceMeeting;
    races: EventWithEventBetTypes<HorseRace, HorseRaceEventBetType>[];
  }[];

  currentBetLine: BetLine;

  notFound = false;
  loading = false;
  HorseRaceStateType = HorseRaceStateType;
  pickerLoading = false;
  HorseRacingFormulaKeyType = HorseRacingFormulaKeyType;
  HorseRacingFormulationBetStateType = HorseRacingFormulationBetStateType;
  HorseRacingRaceCategoryType = HorseRacingRaceCategoryType;
  hasComplement: boolean;
  allowSelectionOverflow: boolean;
  leaveOneBaseEmpty: boolean;
  maxSelection: number;
  isOrdered: boolean;
  horsesSelectionNumber: number[];
  pushSubscriptionSubject = new Subject();
  activeBetSlip: boolean;
  timeoutCanceller;
  description: string;

  showPositions: boolean;
  showStart: boolean;
  showIsGoingLive: boolean;

  currentDate: string;
  changingBetLineEventBetType: boolean;
  isMobileView: boolean;

  constructor(
    private activeRoute: ActivatedRoute,
    private eventsService: EventsService,
    private cdRef: ChangeDetectorRef,
    private router: Router,
    private betSlipService: BetSlipService,
    private pushService: PushService,
    private zone: NgZone,
    private dialogService: DialogService,
    private messageService: MessageService,
    @Inject(PLATFORM_ID) private platId,
    @Optional() private mediaService: MediaService
  ) {
    super();
  }

  ngOnInit() {
    this.pickerLoading = true;
    this.loadRacesSelector();

    this.mediaService?.media$.pipe(takeUntil(this.destroy$)).subscribe(x => {
      if (x === Media.lg || x === Media.xl) {
        this.isMobileView = false;
      } else {
        this.isMobileView = true;
      }
      this.cdRef.markForCheck();
    });

    this.betSlipService.$lines.pipe(takeUntil(this.destroy$)).subscribe(betLine => {
      if (betLine?.lines?.length > 0) {
        this.currentBetLine = betLine.lines[0];
        this.hasComplement = this.currentBetLine.formula?.key === HorseRacingFormulaKeyType.PartWheel;
        this.maxSelection = this.currentBetLine.selectionLength;
        this.allowSelectionOverflow = false;
        this.leaveOneBaseEmpty = false;
        if (
          this.currentBetLine.formula &&
          (this.currentBetLine.formula.key === HorseRacingFormulaKeyType.Combined ||
            this.currentBetLine.formula.key === HorseRacingFormulaKeyType.Unit)
        ) {
          this.allowSelectionOverflow = true;
        } else {
          this.leaveOneBaseEmpty = true;
        }

        this.isOrdered = horseRaceBetTypesConfiguration[this.currentBetLine.betTypeId].isOrdered;
        this.horsesSelectionNumber =
          horseRaceBetTypesConfiguration[this.currentBetLine.betTypeId].selectionNumbersAvailable;

        this.cdRef.markForCheck();
      } else if (!this.changingBetLineEventBetType && this.currentEventBetType) {
        this.betSlipService.addBetLine(this.createEmptyHorseRaceBetLine());

        if (betLine?.reason === BetLineChangeReason.BetRemove || betLine?.reason === BetLineChangeReason.Clear) {
          this.runnerSelection?.resetSelection();
        }
      }
    });

    combineLatest([this.activeRoute.params, this.activeRoute.queryParams]).subscribe(([params, queryParams]) => {
      this.getRaceDetails(params, queryParams);

      this.betSlipService.$refreshEvent.subscribe(_ => {
        this.betSlipService.clear();
        this.getRaceDetails(params, queryParams);
      });
    });

    this.subscribeToPush();

    this.dialogService
      .registerDialog('betslip')
      .pipe(takeUntil(this.destroy$))
      .subscribe(active => {
        this.activeBetSlip = active;
        this.cdRef.markForCheck();
      });
  }

  ngOnDestroy(): void {
    super.ngOnDestroy();
    if (this.timeoutCanceller) {
      clearTimeout(this.timeoutCanceller);
    }
  }

  subscribeToPush() {
    if (this.currentRace) {
      this.pushService.eventChanged$.pipe(takeUntil(this.destroy$)).subscribe(eventChange => {
        if (eventChange.eventId !== this.currentRace.id) {
          return;
        }

        if (eventChange.changes['horseRaceState']) {
          this.currentRace.state = eventChange.changes['horseRaceState'];
        } else if (eventChange.changes['formulations']) {
          const formulationsChange: {
            betTypeId: number;
            state: HorseRacingFormulationBetStateType;
          }[] = eventChange.changes['formulations'];

          this.currentRace.eventBetTypes.forEach(f => {
            const formulationChange = formulationsChange.find(fc => f.betTypeId === fc.betTypeId);
            if (formulationChange) {
              f.betState = formulationChange.state;
            }
          });
        } else if (eventChange.changes['runners']) {
          const runnersChange: {
            number: number;
            nonRunner?: boolean;
            arrivalPosition?: number;
            winnerProbableOdds?: number;
          }[] = eventChange.changes['runners'];

          runnersChange.forEach(r => {
            const targetRunner = this.currentRace.runners.find(rc => r.number === rc.number);
            if (targetRunner) {
              if (r.nonRunner !== undefined) {
                targetRunner.nonRunner = r.nonRunner;
              }
              if (r.arrivalPosition !== undefined) {
                targetRunner.arrivalPosition = r.arrivalPosition;
              }
              if (r.winnerProbableOdds !== undefined) {
                targetRunner.winnerProbableOdds = r.winnerProbableOdds;
              }
            }
          });

          this.currentRace.runners = this.currentRace.runners.slice();
          this.currentRace.activeRunnersCount = this.currentRace.runners.filter(r => !r.nonRunner).length;

          this.formatPositions();
        }
        this.cdRef.markForCheck();
      });
    }
  }

  getRaceDetails(params: Params, queryParams: Params) {
    this.currentDate = queryParams['date'];
    const currentBetTypeId = queryParams['betTypeId'] ? +queryParams['betTypeId'] : undefined;
    const numbers = this.extractNumbersFromPath(params['racePath']);
    this.notFound = false;
    this.loading = true;

    this.eventsService
      .getHorseRaceDetails<EventWithEventBetTypes<HorseRace, HorseRaceEventBetType>>(
        numbers.meetingNumber,
        numbers.raceNumber,
        this.currentDate != undefined ? new Date(this.currentDate) : getDateInBrowserTimeZone()
      )
      .pipe(
        takeUntil(merge(this.destroy$, this.activeRoute.params.pipe(skip(1)))),
        finalize(() => {
          this.loading = false;
        })
      )
      .subscribe(
        race => {
          if (race) {
            this.currentRace = {
              ...race,
              isGoingLive: false,
              activeRunnersCount: race.runners.filter(r => !r.nonRunner).length
            };
            this.pushSubscriptionSubject.next();
            this.formatPositions();
            this.description = this.currentRace.raceConditionDescription;
            this.showPositions =
              this.currentRace.horseRaceState === HorseRaceStateType.TemporaryArrived ||
              this.currentRace.horseRaceState === HorseRaceStateType.DefinitiveArrived ||
              this.currentRace.horseRaceState === HorseRaceStateType.Inquiry ||
              this.currentRace.horseRaceState === HorseRaceStateType.PaymentAuthorized ||
              this.currentRace.horseRaceState === HorseRaceStateType.PaymentStopped;
            this.showStart =
              this.currentRace.horseRaceState === HorseRaceStateType.InSale ||
              this.currentRace.horseRaceState === HorseRaceStateType.Programmed ||
              this.currentRace.horseRaceState === HorseRaceStateType.Undisputed;
            this.showIsGoingLive =
              (this.currentRace.horseRaceState === HorseRaceStateType.InSale ||
                this.currentRace.horseRaceState === HorseRaceStateType.Programmed ||
                this.currentRace.horseRaceState === HorseRaceStateType.Undisputed) &&
              this.currentRace.isGoingLive;

            this.currentEventBetType = currentBetTypeId
              ? race.eventBetTypes?.find(ebt => ebt.betTypeId === currentBetTypeId)
              : null;
            if (
              !this.currentEventBetType ||
              this.currentEventBetType.betState !== HorseRacingFormulationBetStateType.InSale
            ) {
              this.currentEventBetType = race.eventBetTypes?.find(
                ebt => ebt.betState === HorseRacingFormulationBetStateType.InSale
              );
            }

            this.betSlipService.clear();

            const utcNow = getUtcNow();
            const expectedStart = new Date(this.currentRace.expectedStart);
            if (this.currentRace.horseRaceState === HorseRaceStateType.InSale) {
              if (happenBefore(utcNow, expectedStart, environment.delayInMinutesBeforeRaceWillGoLive * 1000 * 60)) {
                this.currentRace.isGoingLive = true;
              } else {
                if (isPlatformBrowser(this.platId)) {
                  this.timeoutCanceller = this.zone.runOutsideAngular(() =>
                    setTimeout(() => {
                      this.currentRace.isGoingLive = true;
                      this.cdRef.markForCheck();
                      // tslint:disable-next-line:max-line-length
                    }, delayBetween(utcNow, new Date(this.currentRace.expectedStart)) - environment.delayInMinutesBeforeRaceWillGoLive * 1000 * 60)
                  );
                }
              }
            }
          }

          this.cdRef.markForCheck();
        },
        error => {
          if (error instanceof HttpErrorResponse) {
            if (error.status === 404) {
              this.notFound = true;
            }
          }
        }
      );
  }

  getFormulas() {
    const horseNumbers = this.currentBetLine?.selectionLength;
    const available =
      this.currentBetLine.baseList?.filter(b => b !== 'X').length <
        horseRaceBetTypesConfiguration[this.currentBetLine.betTypeId].selectionNumber ||
      (horseRaceBetTypesConfiguration[this.currentBetLine.betTypeId].selectionNumbersAvailable?.indexOf(
        horseNumbers
      ) !== -1 &&
        this.currentBetLine.baseList?.filter(b => b !== 'X').length < horseNumbers);
    return this.currentEventBetType.formulas
      .filter(x => x.key !== HorseRacingFormulaKeyType.Combined)
      .map(x => {
        return {
          ...x,
          available: x.key === HorseRacingFormulaKeyType.Unit || available
        };
      });
  }

  getSelectedFormula() {
    if (this.currentBetLine.formula.key === HorseRacingFormulaKeyType.Combined) {
      return this.currentEventBetType.formulas.find(x => x.key === HorseRacingFormulaKeyType.Unit);
    } else {
      return this.currentBetLine.formula;
    }
  }

  toggleSpot() {
    this.runnerSelection?.resetSelection();
    const betLine = setSpot(this.currentBetLine, this.currentEventBetType, !this.currentBetLine?.quickPick);
    this.betSlipService.updateBetLine(betLine);
  }

  trackByFormulas(_index, formula) {
    return formula.key;
  }

  private extractNumbersFromPath(racePath: string) {
    const numberRegex = /R(\d+)C(\d+)/;
    const matchs = racePath.match(numberRegex);
    return {
      raceNumber: +matchs[2],
      meetingNumber: +matchs[1]
    };
  }

  raceChanged(race: { meetingNumber: number; raceNumber: number; date: string }) {
    const params = {};
    if (race.date) {
      params['date'] = race.date;
    }

    this.router.navigate(['/horseracing/race', `R${race.meetingNumber}C${race.raceNumber}`], {
      relativeTo: this.activeRoute,
      queryParams: params
    });
  }

  selectionChanged(selection: RunnersSelection) {
    const betLine = this.changeSelection(this.currentBetLine, selection);
    this.betSlipService.updateBetLine(betLine);
  }

  selectEventBetType(eventBetType: HorseRaceEventBetType) {
    if (
      eventBetType.betState !== HorseRacingFormulationBetStateType.InSale ||
      eventBetType.id === this.currentBetLine.eventBetTypeId
    ) {
      return;
    }

    this.currentEventBetType = eventBetType;
    this.runnerSelection.resetSelection();

    this.changingBetLineEventBetType = true;
    this.betSlipService.clear();
    this.betSlipService.addBetLine(
      this.createEmptyHorseRaceBetLine(
        this.currentEventBetType.formulas.find(f => f.key === HorseRacingFormulaKeyType.Unit)
      )
    );
    this.changingBetLineEventBetType = false;
  }

  popinBettypesInformations() {
    this.messageService.sendComponentMessage(PopinBettypesInformationsComponent, {
      currentBetTypeId: this.currentEventBetType.betTypeId,
      betTypes: this.currentRace.eventBetTypes.map(i => {
        return {
          id: i.betTypeId,
          booster: i.booster
        };
      })
    });
  }

  openPopinRaceConditions() {
    this.messageService.sendComponentMessage(PopinRaceConditionsComponent, {
      description: this.description,
      name: this.currentRace.name
    });
  }

  selectFormula(formula: Formula) {
    if (formula.key !== this.currentBetLine.formula.key) {
      const selectionLength = formula.multiValues?.indexOf(this.currentBetLine.selectionLength)
        ? this.currentBetLine.selectionLength
        : formula.multiValues?.[0] || horseRaceBetTypesConfiguration[this.currentBetLine.betTypeId].selectionNumber;
      const betLineToUpdate = {
        ...this.currentBetLine,
        formula: formula,
        selectionLength: selectionLength,
        multiValue: selectionLength
      };

      this.betSlipService.updateBetLine(betLineToUpdate);
    }
  }

  openBetSlip() {
    this.dialogService.toggleDialog('betslip', !this.activeBetSlip);
  }

  changeHorsesNumber(number: number) {
    const betLine = this.setSelectionNumber(this.currentBetLine, number);
    this.betSlipService.updateBetLine(betLine);
  }

  getSubscription(): Observable<{ eventSubscriptions: number[]; betTypeSubscriptions: number[] }> {
    return this.pushSubscriptionSubject.pipe(
      map(() => ({
        eventSubscriptions: [this.currentRace.id],
        betTypeSubscriptions: []
      }))
    );
  }

  formatPositions(): string {
    const positions: HorseRaceRunner[][] = [];

    this.currentRace.runners.map(r => {
      if (!r.arrivalPosition) {
        return;
      }

      if (!positions[r.arrivalPosition - 1]) {
        positions[r.arrivalPosition - 1] = [];
      }

      if (r.arrivalPosition <= 5) {
        positions[r.arrivalPosition - 1].push(r);
      }
    });

    return positions
      .map(p => p.map(r => r.number).join('/'))
      .filter(Boolean)
      .join('-');
  }

  createEmptyHorseRaceBetLine(formula?: Formula): BetLine {
    return createHorseRaceBetLine(
      this.currentRace,
      this.currentEventBetType,
      [],
      null,
      formula ?? this.currentEventBetType.formulas.find(f => f.key === HorseRacingFormulaKeyType.Unit),
      false,
      null,
      null,
      formula?.quickPickAllowed ??
        this.currentEventBetType.formulas.find(f => f.key === HorseRacingFormulaKeyType.Unit).quickPickAllowed
        ? false
        : null,
      this.currentEventBetType.allowedMultipliers
    );
  }

  changeSelection(betLine: BetLine, selection: RunnersSelection): BetLine {
    const betLineToUpdate = {
      ...betLine
    };

    const baseList = selection.bases.sort((i1, i2) => i1.index - i2.index);

    if (
      betLineToUpdate.formula.key === HorseRacingFormulaKeyType.PartWheel ||
      betLineToUpdate.formula.key === HorseRacingFormulaKeyType.Wheel
    ) {
      betLineToUpdate.baseList = new Array(betLineToUpdate.selectionLength).fill('X');
      baseList.forEach(b => (betLineToUpdate.baseList[b.index - 1] = b.number.toString()));
    } else if (betLineToUpdate.quickPick) {
      betLineToUpdate.baseList = new Array(betLineToUpdate.selectionLength).fill('Y');
      baseList.forEach(b => (betLineToUpdate.baseList[b.index - 1] = b.number.toString()));
    } else {
      betLineToUpdate.baseList = baseList.map(x => `${x.number}`);
    }

    if (
      betLineToUpdate.formula.key === HorseRacingFormulaKeyType.Unit &&
      betLineToUpdate.selectionLength < baseList.length
    ) {
      betLineToUpdate.formula = this.currentEventBetType.formulas.find(
        x => x.key === HorseRacingFormulaKeyType.Combined
      );
    } else if (
      betLineToUpdate.formula.key === HorseRacingFormulaKeyType.Combined &&
      betLineToUpdate.selectionLength >= baseList.length
    ) {
      betLineToUpdate.formula = this.currentEventBetType.formulas.find(x => x.key === HorseRacingFormulaKeyType.Unit);
    }

    if (betLineToUpdate.formula.key === HorseRacingFormulaKeyType.PartWheel) {
      betLineToUpdate.associatedList = selection.complements.map(x => `${x}`);
    } else {
      betLineToUpdate.associatedList = null;
    }

    return betLineToUpdate;
  }

  setSelectionNumber(betLine: BetLine, number: number): BetLine {
    const betLineToUpdate = {
      ...betLine
    };

    if (
      !horseRaceBetTypesConfiguration[this.currentEventBetType.betTypeId].selectionNumber &&
      horseRaceBetTypesConfiguration[this.currentEventBetType.betTypeId].selectionNumbersAvailable.indexOf(number) !==
        -1
    ) {
      betLineToUpdate.selectionLength = number;
      betLineToUpdate.multiValue = number;
      if (betLineToUpdate.quickPick) {
        betLineToUpdate.baseList.splice(betLineToUpdate.selectionLength);
        betLineToUpdate.baseList = [
          ...betLineToUpdate.baseList,
          ...new Array(betLineToUpdate.selectionLength - betLineToUpdate.baseList.length).fill('Y')
        ];
      }

      if (
        betLineToUpdate.formula.key === HorseRacingFormulaKeyType.PartWheel ||
        betLineToUpdate.formula.key === HorseRacingFormulaKeyType.Wheel
      ) {
        betLineToUpdate.baseList.splice(betLineToUpdate.selectionLength);
        betLineToUpdate.baseList = [
          ...betLineToUpdate.baseList,
          ...new Array(betLineToUpdate.selectionLength - betLineToUpdate.baseList.length).fill('X')
        ];
      }
    }

    return betLineToUpdate;
  }

  loadRacesSelector() {
    this.currentDate = this.activeRoute.snapshot.queryParams['date'];
    this.eventsService
      .getHorseRacesOfTheDay(getDateInBrowserTimeZone())
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.pickerLoading = false;
        })
      )
      .subscribe(races => {
        const racesByMeetingId = races.reduce<{
          [meetingId: number]: EventWithEventBetTypes<HorseRace, HorseRaceEventBetType>[];
        }>((meetings, race) => {
          if (!meetings[race.meeting.number]) {
            meetings[race.meeting.number] = [];
          }

          meetings[race.meeting.number].push(race);

          return meetings;
        }, []);

        this.racesPerMeetings = [];
        for (const meetingId in racesByMeetingId) {
          this.racesPerMeetings.push({
            meeting: racesByMeetingId[meetingId][0].meeting,
            races: racesByMeetingId[meetingId]
          });
        }
        this.cdRef.markForCheck();
      });
  }
}
