import { Component, OnInit, ChangeDetectionStrategy, ChangeDetectorRef, Inject } from '@angular/core';
import { DatePipe } from '@angular/common';
import { EnabledDisabledMode, operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';
import { I18nService } from '@honoregaming/i18n';
import { TelemetryService } from '@honoregaming/customer-core';
import { DestroySubject } from '@honoregaming/core';
import { takeUntil } from 'rxjs/operators';

@Component({
  selector: 'hg-races-results-pdf',
  templateUrl: './races-results-pdf.component.html',
  styleUrls: ['./races-results-pdf.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [DatePipe]
})
export class RacesResultsPdfComponent extends DestroySubject implements OnInit {
  constructor(
    public i18nService: I18nService,
    private telemetryService: TelemetryService,
    private cdRef: ChangeDetectorRef,
    private datePipe: DatePipe,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration
  ) {
    super();
  }

  userLanguage: string;
  resultsInfos: { date: Date; urlStart: string; urlEnd: string }[];
  basePmupUrl = this.operatorConfiguration.horseRacingConfiguration.horseRacingCouponPmupUrl;
  numbersOfDays = 3;

  ngOnInit() {
    this.i18nService.languageChanged$.pipe(takeUntil(this.destroy$)).subscribe(l => {
      this.userLanguage = l;
      this.cdRef.markForCheck();
    });

    this.userLanguage = this.i18nService.currentLanguageCode;

    if (this.operatorConfiguration.features.horseRacingFeatures.couponMode === EnabledDisabledMode.Enabled) {
      this.resultsInfos = [];
      let day = new Date();

      while (this.resultsInfos.length < this.numbersOfDays) {
        const date = new Date(day.setDate(day.getDate() - 1));
        const stringDate = this.datePipe.transform(date, 'yyyy-MM-dd');
        this.resultsInfos.push({
          date: date,
          urlStart: this.basePmupUrl + 'results/',
          urlEnd: '/' + stringDate + '.pdf'
        });
      }

      day = new Date();
      day.setDate(day.getDate() - 2);
    }
  }

  logEvent(coupon: { date: Date; urlStart: string; urlEnd: string }, type: 'Odds' | 'Results') {
    this.telemetryService.trackEvent('Coupon.HorseRacing.Download', { date: coupon.date, type });
  }
}
