import {
  Component,
  ChangeDetectionStrategy,
  Input,
  Output,
  EventEmitter,
  ChangeDetectorRef,
  OnChanges,
  SimpleChanges,
  OnInit,
  HostBinding
} from '@angular/core';
import { finalize } from 'rxjs/operators';
import { EventsService } from '@honoregaming/events';
import {
  HorseRaceRunner,
  HorseRaceRunnerInformations,
  HorseRacingBlinderType,
  HorseRacingUnshodType
} from '@honoregaming/types';
import { RunnersSelection } from '../../models/runners-selection.model';
import { getBaseListMaximumLengthOffset } from '@honoregaming/core';

@Component({
  selector: 'hg-horseracing-runners-selection',
  templateUrl: './runners-selection.component.html',
  styleUrls: ['./runners-selection.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class RunnersSelectionComponent implements OnInit, OnChanges {
  @Input()
  runners: HorseRaceRunner[];

  @Input()
  maxSelection = 5;

  @Input()
  allowOverflow = true;

  @Input()
  leaveOneBaseEmpty = true;

  @Input()
  hasComplement = false;

  @Input()
  ordered = false;

  @Input()
  disable = false;

  @Input()
  baseListMaximumLengthOffset?: number;

  @Input()
  maximumNumberOfRunnersToApplyBaseListMaximumLengthOffset?: number;

  @Input()
  selectionLength: number = 0;

  @Output()
  selectionChanged = new EventEmitter<RunnersSelection>();

  orderedRunners: (HorseRaceRunner & {
    index?: number;
    complement?: boolean;
    informations?: HorseRaceRunnerInformations;
    loadingInformations?: boolean;
    showMoreInformations?: boolean;
  })[];

  HorseRacingUnshodType = HorseRacingUnshodType;
  HorseRacingBlinderType = HorseRacingBlinderType;

  sortOrderNumber = SortOrder.ascending;
  sortOrderOdd = SortOrder.ascending;

  constructor(private cdRef: ChangeDetectorRef, private eventsService: EventsService) {}

  ngOnInit(): void {
    this.orderedRunners = [...this.runners];
  }

  ngOnChanges(_changes: SimpleChanges): void {
    if (this.orderedRunners) {
      this.runners
        .filter(r => r.nonRunner)
        .forEach(r => {
          const runner = this.orderedRunners.find(rc => r.number === rc.number);
          if (runner) {
            runner.index = runner.nonRunner ? null : runner.index;
            runner.complement = runner.nonRunner ? null : runner.complement;
          }
        });

      this.selectionChanged.emit({
        bases: this.orderedRunners
          .filter(r => r.index)
          .map(r => {
            return {
              number: r.number,
              index: r.index
            };
          }),
        complements: this.orderedRunners.filter(r => r.complement).map(r => r.number)
      });
    }
  }

  runnerClickSelection(runner: HorseRaceRunner & { index?: number; complement?: boolean }) {
    if (runner.nonRunner) {
      return;
    }

    if (runner.index && !this.ordered) {
      runner.index = null;
    } else {
      runner.index = this.getNextAvailableIndex(runner.index);

      if (!runner.index && !this.leaveOneBaseEmpty) {
        this.flattenIndexes();
      }

      if (runner.complement && runner.index) {
        runner.complement = null;
      }
    }

    if (!this.canAddRunner()) {
      runner.index = null;
    }

    this.selectionChanged.emit({
      bases: this.orderedRunners
        .filter(r => r.index)
        .map(r => {
          return {
            number: r.number,
            index: r.index
          };
        }),
      complements: this.orderedRunners.filter(r => r.complement).map(r => r.number)
    });

    this.cdRef.markForCheck();
  }

  runnerClickComplement(runner: HorseRaceRunner & { index?: number; complement?: boolean }) {
    if (runner.nonRunner) {
      return;
    }

    runner.complement = !runner.complement;
    if (runner.complement && runner.index) {
      runner.index = null;
    }

    this.selectionChanged.emit({
      bases: this.orderedRunners
        .filter(r => r.index)
        .map(r => {
          return {
            number: r.number,
            index: r.index
          };
        }),
      complements: this.orderedRunners.filter(r => r.complement).map(r => r.number)
    });
    this.cdRef.markForCheck();
  }

  resetSelection() {
    this.orderedRunners.forEach(x => {
      x.index = undefined;
      x.complement = undefined;
    });

    this.cdRef.markForCheck();
  }

  private getNextAvailableIndex(currentIndex: number): number {
    // If there is no slot available because of leaveOneBaseEmpty, just do nothing
    if (
      !currentIndex &&
      this.leaveOneBaseEmpty &&
      this.orderedRunners.filter(r => r.index).length >= this.maxSelection - 1
    ) {
      return null;
    }

    const indexes: number[] = Array(this.orderedRunners.length);
    for (let i = 0; i < this.orderedRunners.length; i++) {
      indexes[i] = i + 1;
    }

    this.orderedRunners.filter(r => r.index).forEach(r => (indexes[r.index - 1] = null));
    let targetIndex = indexes.filter(r => r).find(i => !currentIndex || i > currentIndex);
    // If index is in overflow, and all mandatory slots are not full, just cancel the found index
    if (
      targetIndex > this.maxSelection &&
      (targetIndex === currentIndex + 1 || (currentIndex && currentIndex <= this.maxSelection))
    ) {
      targetIndex = null;
    }

    // If index is set but current index is over the max selection, just cancel the found index
    if (targetIndex && currentIndex && currentIndex > this.maxSelection) {
      targetIndex = null;
    }

    // If all slots are full and no overflow is allowed, just cancel the found index
    if (targetIndex > this.maxSelection && !this.allowOverflow) {
      targetIndex = null;
    }

    return targetIndex;
  }

  @HostBinding('class.selection-disabled')
  get cantMakeNewSelection() {
    if (this.allowOverflow) {
      return false;
    }

    const currentSelectionLength = this.orderedRunners.filter(r => r.index).length;
    if (
      (!this.leaveOneBaseEmpty && currentSelectionLength >= this.maxSelection) ||
      (this.leaveOneBaseEmpty && currentSelectionLength >= this.maxSelection - 1)
    ) {
      return true;
    }

    return false;
  }

  flattenIndexes() {
    let i = 1;
    this.orderedRunners
      .filter(r => r.index)
      .sort((r1, r2) => r1.index - r2.index)
      .forEach(r => (r.index = i++));
  }

  canAddRunner() {
    var numberOfRunners = this.runners.filter(r => !r.nonRunner).length;
    if (
      this.selectionLength >=
      numberOfRunners -
        getBaseListMaximumLengthOffset(
          numberOfRunners,
          this.baseListMaximumLengthOffset,
          this.maximumNumberOfRunnersToApplyBaseListMaximumLengthOffset
        )
    ) {
      return false;
    }

    return true;
  }

  showMoreInformations(
    runner: HorseRaceRunner & {
      index?: number;
      complement?: boolean;
      informations?: HorseRaceRunnerInformations;
      loadingInformations?: boolean;
      showMoreInformations?: boolean;
    }
  ) {
    runner.showMoreInformations = !runner.showMoreInformations;

    if (runner.showMoreInformations) {
      if (!runner.informations) {
        runner.loadingInformations = true;
        this.eventsService
          .getHorseRaceRunnerInformations(runner.id)
          .pipe(
            finalize(() => {
              runner.loadingInformations = false;
            })
          )
          .subscribe(info => {
            runner.informations = info;
            this.cdRef.markForCheck();
          });
      }
    }
  }

  sort(
    key: keyof (HorseRaceRunner & {
      index?: number;
      complement?: boolean;
      informations?: HorseRaceRunnerInformations;
      loadingInformations?: boolean;
      showMoreInformations?: boolean;
    }),
    isNumberKey: boolean
  ) {
    let sortOrder: SortOrder;
    if (isNumberKey) {
      this.sortOrderNumber = this.sortOrderNumber === SortOrder.ascending ? SortOrder.descending : SortOrder.ascending;
      sortOrder = this.sortOrderNumber;
    } else {
      this.sortOrderOdd = this.sortOrderOdd === SortOrder.ascending ? SortOrder.descending : SortOrder.ascending;
      sortOrder = this.sortOrderOdd;
    }

    this.orderedRunners.sort((x, y) => {
      let keyX = x[key];
      let keyY = y[key];
      let compair = 0;

      if (keyX < keyY) {
        compair = -1;
      } else if (keyX > keyY) {
        compair = 1;
      }

      if (sortOrder === SortOrder.descending) {
        compair = compair * -1;
      }

      return compair;
    });
  }
}

export enum SortOrder {
  ascending,
  descending
}
