import { Component, ChangeDetectionStrategy, Inject, PLATFORM_ID, ChangeDetectorRef } from '@angular/core';
import { isPlatformServer } from '@angular/common';
import { HorseRacingMenuBaseComponent } from '../horse-racing-menu-base.component';
import { DialogService } from '@honoregaming/core';
import { MenuCustomizationService } from '@honoregaming/customer-core';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { MessageService } from '@honoregaming/ui';

@Component({
  selector: 'hg-horse-racing-menu',
  templateUrl: './horse-racing-menu.component.html',
  styleUrls: ['./horse-racing-menu.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class HorseRacingMenuComponent extends HorseRacingMenuBaseComponent {
  public isServer = isPlatformServer(this.platformId);

  constructor(
    @Inject(PLATFORM_ID) private platformId,
    cdRef: ChangeDetectorRef,
    dialogService: DialogService,
    messageService: MessageService,
    menuCustomizationService: MenuCustomizationService,
    @Inject(operatorConfigurationToken) operatorConfiguration: OperatorConfiguration
  ) {
    super(cdRef, dialogService, messageService, menuCustomizationService, operatorConfiguration);
  }
}
