import {
  Component,
  ChangeDetectionStrategy,
  OnInit,
  Inject,
  Output,
  EventEmitter,
  ChangeDetectorRef,
  HostBinding,
  OnDestroy
} from '@angular/core';
import { AuthService } from '@honoregaming/customer-core';
import { DOCUMENT } from '@angular/common';
import { EventsService } from '@honoregaming/events';
import { DestroySubject, DialogService } from '@honoregaming/core';
import { takeUntil } from 'rxjs/operators';
import { globalConfiguration } from '@honoregaming/configuration';

@Component({
  selector: 'hg-horseracing-video-player',
  templateUrl: './horseracing-video-player.component.html',
  styleUrls: ['./horseracing-video-player.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class HorseRacingVideoPlayerComponent extends DestroySubject implements OnInit, OnDestroy {
  @Output()
  closePlayer: EventEmitter<any> = new EventEmitter();

  private clapprScriptId = 'clappr_script';

  @HostBinding('class.isHidden')
  private isHidden = true;

  private script: HTMLScriptElement;

  public isLoading = false;
  public isUserLoggedIn = false;
  public player: any = null;

  constructor(
    @Inject(DOCUMENT) private document,
    private cdRef: ChangeDetectorRef,
    private authService: AuthService,
    private eventsService: EventsService,
    private dialogService: DialogService
  ) {
    super();
  }

  ngOnInit(): void {
    this.script = this.document.createElement('script');
    this.script.type = 'text/javascript';
    this.script.src = `${globalConfiguration.staticAssetsPath}clappr.min.js`;
    this.script.id = this.clapprScriptId;

    this.authService.me$.pipe(takeUntil(this.destroy$)).subscribe(me => {
      if (this.isUserLoggedIn !== !!me) {
        this.isUserLoggedIn = !this.isUserLoggedIn;
        this.cdRef.markForCheck();
        this.displayVideoPlayer();
      }
    });

    this.dialogService
      .registerDialog('horseracing-livestream')
      .pipe(takeUntil(this.destroy$))
      .subscribe(state => {
        if (state) {
          this.isHidden = false;
          this.displayVideoPlayer();
        } else {
          this.isHidden = true;
          this.stopVideoPlayer();
        }
      });
  }

  ngOnDestroy(): void {
    super.ngOnDestroy();

    this.closePlayer.emit();
  }

  displayVideoPlayer(): void {
    if (this.isUserLoggedIn && !this.isHidden) {
      this.isLoading = true;
      this.cdRef.markForCheck();

      // Call api to get URL
      this.eventsService.getStreamingUrl().subscribe(streaminInfos => {
        const streamingUrl = streaminInfos.url;

        // Just add the script once if it's not already there
        if (this.document.getElementById(this.clapprScriptId) == null) {
          this.document.querySelector('head').appendChild(this.script);

          this.script.onload = () => {
            this.setupVideoPlayer(streamingUrl);
          };
        } else {
          this.setupVideoPlayer(streamingUrl);
        }
      });
    } else {
      // User disconnect so clean resources
      this.stopVideoPlayer();
    }
  }

  setupVideoPlayer(streamingUrl: string): void {
    if (
      this.document.getElementById(this.clapprScriptId) != null &&
      this.document.getElementsByClassName('target-video').length
    ) {
      this.stopVideoPlayer();

      this.player = new (<any>window).Clappr.Player({
        source: streamingUrl,
        autoPlay: false,
        parentId: '#player',
        height: '100%',
        width: '100%'
      });

      this.isLoading = false;
      this.cdRef.markForCheck();
    }
  }

  stopVideoPlayer(): void {
    if (
      this.document.getElementById(this.clapprScriptId) != null &&
      this.document.getElementsByClassName('target-video').length &&
      this.player != null
    ) {
      this.player.stop();
      this.player.destroy();
      this.player = null;
    }
  }

  closeVideoPlayer(): void {
    this.isHidden = true;
    this.stopVideoPlayer();

    this.closePlayer.emit();
  }

  showConnectionView(): void {
    this.dialogService.toggleDialog('login', true);
  }
}
