import { Component, OnInit, ChangeDetectionStrategy, Input } from '@angular/core';

@Component({
  selector: 'hg-popin-race-conditions',
  templateUrl: './popin-race-conditions.component.html',
  styleUrls: ['./popin-race-conditions.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class PopinRaceConditionsComponent implements OnInit {
  @Input() description: string;
  @Input() name: string;

  constructor() {}

  ngOnInit() {
    this.description = this.description.replace(/-/g, '').replace(this.name, '');
  }
}
