import { isPlatformBrowser } from '@angular/common';
import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  Inject,
  NgZone,
  OnDestroy,
  OnInit,
  PLATFORM_ID
} from '@angular/core';
import { DestroySubject, getDateInBrowserTimeZone, PushService } from '@honoregaming/core';
import { delayBetween, getUtcNow, happenBefore } from '@honoregaming/customer-core';
import { DataSourceId, EventsService } from '@honoregaming/events';
import {
  EventWithEventBetTypes,
  HorseRace,
  HorseRaceEventBetType,
  HorseRaceMeeting,
  HorseRaceStateType,
  HorseRacingFormulationBetStateType,
  HorseRacingRaceCategoryType
} from '@honoregaming/types';
import { Subject, Subscription } from 'rxjs';
import { finalize, takeUntil } from 'rxjs/operators';
import { environment } from '../../../../../customer/src/environments/environment';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';

@Component({
  selector: 'hg-upcoming-races',
  templateUrl: './upcoming-races.component.html',
  styleUrls: ['./upcoming-races.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class UpcomingRacesComponent extends DestroySubject implements OnInit, OnDestroy {
  nextRaces: { race: HorseRace; isGoingLive: boolean; meeting: HorseRaceMeeting }[];
  racesPerMeetings: {
    meeting: HorseRaceMeeting;
    races: (EventWithEventBetTypes<HorseRace, HorseRaceEventBetType> & {
      quintePlus: { exists: boolean; booster: boolean };
    })[];
    raceCategories?: HorseRacingRaceCategoryType[];
  }[];

  pushSubscriptionSubject = new Subject();
  pushSub: Subscription;

  timeoutCanceller;

  loading = false;

  nextQuintePlus: any;

  displayBetCategoryNameOnMobile = this.operatorConfiguration.onlineConfiguration?.showBetCategoryNameOnMobile;

  constructor(
    private eventsService: EventsService,
    private zone: NgZone,
    private cdRef: ChangeDetectorRef,
    private pushService: PushService,
    @Inject(PLATFORM_ID) private platId,
    @Inject(operatorConfigurationToken) public operatorConfiguration: OperatorConfiguration
  ) {
    super();
  }

  ngOnInit() {
    this.loading = true;

    this.eventsService
      .getHorseRacesOfTheDay(getDateInBrowserTimeZone())
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(races => {
        const racesByMeetingId = races.reduce<{
          [meetingId: number]: {
            races: (EventWithEventBetTypes<HorseRace, HorseRaceEventBetType> & {
              quintePlus: { exists: boolean; booster: boolean };
            })[];
            quintePlus: { exists: boolean; booster: boolean };
          };
        }>((meetings, race) => {
          if (!meetings[race.meeting.number]) {
            meetings[race.meeting.number] = {
              races: [],
              quintePlus: { exists: false, booster: false }
            };
          }

          let quintePlusEventBetType = race.eventBetTypes.find(
            ebt => ebt.betTypeId === 14 && ebt.betState === HorseRacingFormulationBetStateType.InSale
          );
          meetings[race.meeting.number].races.push({
            ...race,
            quintePlus: { exists: quintePlusEventBetType != null, booster: quintePlusEventBetType?.booster ?? false }
          });

          quintePlusEventBetType = race.eventBetTypes.find(ebt => ebt.betTypeId === 14);
          if (quintePlusEventBetType != null) {
            meetings[race.meeting.number].quintePlus = { exists: true, booster: quintePlusEventBetType.booster };
          }

          return meetings;
        }, []);

        this.racesPerMeetings = [];
        for (const meetingId in racesByMeetingId) {
          this.racesPerMeetings.push({
            meeting: racesByMeetingId[meetingId].races[0].meeting,
            races: racesByMeetingId[meetingId].races,
            raceCategories: racesByMeetingId[meetingId].races.map(r => r.category)
          });
        }

        this.pushSubscriptionSubject.next();

        this.aggregateNextRaces();
        this.markNextRacesHasGoingLive();

        this.zone.runOutsideAngular(() => {
          this.subscribeToNextRaceGoingLive();
        });

        // Fill meeting with fake races
        const maxRacesCount = Math.max(...this.racesPerMeetings.map(m => m.races.length));
        this.racesPerMeetings = this.racesPerMeetings.map(m => {
          const newMeeting = { ...m };
          if (m.races.length < maxRacesCount) {
            newMeeting.races = [...m.races, ...new Array(maxRacesCount - m.races.length)];
          }

          return newMeeting;
        });

        this.pushSub = this.pushService.eventChanged$.pipe(takeUntil(this.destroy$)).subscribe(changes => {
          let raceIndex: number;
          const meetingIndex = this.racesPerMeetings?.findIndex(x => {
            raceIndex = x.races.findIndex(r => r && r.id === changes.eventId);
            return raceIndex >= 0;
          });

          if (meetingIndex >= 0) {
            const race = this.racesPerMeetings[meetingIndex].races[raceIndex];
            if (changes.changes['horseRaceState']) {
              race.state = changes.changes['horseRaceState'];
            } else if (changes.changes['formulations']) {
              const formulationsChange: {
                betTypeId: number;
                state: HorseRacingFormulationBetStateType;
              }[] = changes.changes['formulations'];

              race.eventBetTypes.forEach(f => {
                const formulationChange = formulationsChange.find(fc => f.betTypeId === fc.betTypeId);
                if (formulationChange) {
                  f.betState = formulationChange.state;
                }
              });
            }
            this.aggregateNextRaces();
            this.markNextRacesHasGoingLive();
            this.cdRef.markForCheck();
          }
        });
      });

    this.nextQuintePlusGoingLive();
  }

  aggregateNextRaces() {
    if (!this.racesPerMeetings?.length) {
      return;
    }

    this.nextRaces = this.racesPerMeetings
      .map(m =>
        m.races
          .filter(
            r =>
              r !== undefined &&
              (r.dataSourceId !== DataSourceId.Manual || getUtcNow() < new Date(r.expectedStart)) &&
              (r.horseRaceState === HorseRaceStateType.InSale || r.horseRaceState === HorseRaceStateType.Start)
          )
          .map(r => {
            return { race: r, meeting: r.meeting, isGoingLive: false };
          })
      )
      .reduce((r1, r2) => r1.concat(r2))
      .sort((r1, r2) => +new Date(r1.race.expectedStart) - +new Date(r2.race.expectedStart))
      .slice(0, 4);
  }

  markNextRacesHasGoingLive() {
    const utcNow = getUtcNow();

    this.nextRaces?.forEach(r => {
      if (
        happenBefore(utcNow, new Date(r.race.expectedStart), environment.delayInMinutesBeforeRaceWillGoLive * 1000 * 60)
      ) {
        r.isGoingLive = true;
      } else {
        r.isGoingLive = false;
      }
    });

    this.cdRef.markForCheck();
  }

  nextQuintePlusGoingLive() {
    this.eventsService
      .getNextQuinte(true, getDateInBrowserTimeZone(), null, 1, true)
      .pipe(takeUntil(this.destroy$))
      .subscribe(quintePlus => {
        this.nextQuintePlus = quintePlus;
        this.cdRef.markForCheck();
      });
  }

  subscribeToNextRaceGoingLive() {
    if (this.timeoutCanceller) {
      this.timeoutCanceller();
    }

    const utcNow = getUtcNow();

    const nextRace = this.nextRaces?.find(r => new Date(r.race.expectedStart) > utcNow);
    if (nextRace && isPlatformBrowser(this.platId)) {
      this.timeoutCanceller = setTimeout(() => {
        this.markNextRacesHasGoingLive();
      }, delayBetween(utcNow, new Date(nextRace.race.expectedStart)) - environment.delayInMinutesBeforeRaceWillGoLive * 1000 * 60);
    }
  }

  // tslint:disable-next-line: use-life-cycle-interface
  ngOnDestroy(): void {
    super.ngOnDestroy();

    if (this.timeoutCanceller) {
      clearTimeout(this.timeoutCanceller);
    }
    // this.pushSub.unsubscribe();
  }

  trackRace(_index: number, race: { race: HorseRace; isGoingLive: boolean; meeting: HorseRaceMeeting }) {
    return race.race.id;
  }
}
