import {
  Component,
  ChangeDetectionStrategy,
  OnInit,
  ChangeDetectorRef,
  OnDestroy,
  Inject,
  Optional
} from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { DestroySubject, getInexactOrder } from '@honoregaming/core';
import { customerOperatorConfigurationToken, CustomerOperatorConfiguration } from '@honoregaming/customer-core';
import { EventsService } from '@honoregaming/events';
import { HorseRaceDividend, HorseRaceWithDividendsDisplayModel, RaceDividendType } from '@honoregaming/types';
import { Media, MediaService } from '@honoregaming/ui';
import { finalize, switchMap } from 'rxjs/operators';
import { DisplayMode } from '../../enums/display-mode.enum';

@Component({
  selector: 'hg-race-results-details',
  templateUrl: './race-results-details.component.html',
  styleUrls: ['./race-results-details.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class RaceResultsDetailsComponent extends DestroySubject implements OnInit, OnDestroy {
  loading = false;
  raceWithDividends: HorseRaceWithDividendsDisplayModel;
  groupedArrival: { position: number; runners: number[] }[];

  betTypes: { name: string; id: number; iconUrl: string }[];
  currentSelectedBetType: number;

  displayModes: { label: string; id: number }[]; // by base amount or by currency (only base amount used for now)
  currencySymbol: string;

  raceDividendTypes = RaceDividendType;
  hasDividends: boolean;

  media: Media;
  MediaEnum = Media;

  constructor(
    private eventsService: EventsService,
    private cdRef: ChangeDetectorRef,
    private route: ActivatedRoute,
    @Inject(customerOperatorConfigurationToken) private operatorConfiguration: CustomerOperatorConfiguration,
    @Optional() private mediaService: MediaService
  ) {
    super();
  }

  ngOnInit() {
    this.mediaService?.media$.subscribe(x => (this.media = x));
    this.loadDetails();
  }

  loadDetails() {
    this.loading = true;
    this.route.params
      .pipe(
        switchMap(params => {
          return this.eventsService.getHorseRaceResultsDetails(params['raceId']).pipe(
            finalize(() => {
              this.loading = false;
            })
          );
        })
      )
      .subscribe(raceWithDividends => {
        this.raceWithDividends = raceWithDividends;
        this.groupedArrival = raceWithDividends.groupedArrival;
        this.betTypes = this.getDividendsBetTypes();
        this.currencySymbol = this.operatorConfiguration.currency.symbol;
        this.hasDividends = Object.keys(this.raceWithDividends.dividends).length > 0;
        if (this.hasDividends) {
          this.displayModes = [
            { label: `1 ${this.currencySymbol}`, id: DisplayMode.ByCurrency },
            {
              label: `${
                this.raceWithDividends.dividends[Object.keys(this.raceWithDividends.dividends)[0]][0].baseAmount
              } ${this.currencySymbol}`,
              id: DisplayMode.ByBaseAmount
            }
          ];
          this.currentSelectedBetType =
            this.raceWithDividends.dividends[Object.keys(this.raceWithDividends.dividends)[0]][0].betTypeId;
        }
        this.cdRef.markForCheck();
      });
  }

  getDisplayedCombination(dividend: HorseRaceDividend): string {
    return dividend.type === RaceDividendType.InexactOrder
      ? getInexactOrder(dividend.combination, ' ')
      : dividend.combination;
  }

  getDividendsBetTypes(): { name: string; id: number; iconUrl: string }[] {
    return Object.keys(this.raceWithDividends.dividends).map(e => {
      return {
        name: this.raceWithDividends.dividends[e][0].betType,
        id: this.raceWithDividends.dividends[e][0].betTypeId,
        iconUrl: this.raceWithDividends.dividends[e][0].betTypeIconUrl
      };
    });
  }

  updateCurrentBetType(id: number) {
    this.currentSelectedBetType = id;
    this.displayModes[1].label = `${this.raceWithDividends.dividends[this.currentSelectedBetType][0].baseAmount} ${
      this.currencySymbol
    }`;
    this.cdRef.markForCheck();
  }
}
