import { Component, OnInit, ChangeDetectionStrategy, ChangeDetectorRef, Inject, OnDestroy } from '@angular/core';
import { EnabledDisabledMode, operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';
import { DialogService } from '@honoregaming/core';
import { MessageService, WarningDataComponent } from '@honoregaming/ui';
import { Subject } from 'rxjs';
import { filter, takeUntil } from 'rxjs/operators';
import { NavigationEnd, Router } from '@angular/router';

@Component({
  selector: 'hg-nav-header',
  templateUrl: './nav-header.component.html',
  styleUrls: ['./nav-header.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class NavHeaderComponent implements OnInit, OnDestroy {
  private destroy$: Subject<boolean> = new Subject<boolean>();

  public isStreamingAvailable: boolean =
    this.operatorConfiguration.features.horseRacingFeatures.streamingMode === EnabledDisabledMode.Enabled;
  public isVideoPlayerVisible: boolean;

  warnOnDataConsumption = this.operatorConfiguration.onlineConfiguration?.warnOnDataConsumption;
  showBanners: boolean;
  isAboutPage = false;

  constructor(
    private cdRef: ChangeDetectorRef,
    private dialogService: DialogService,
    private messageService: MessageService,
    private router: Router,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration
  ) {}
  ngOnInit() {
    this.dialogService
      .registerDialog('horseracing-livestream')
      .pipe(takeUntil(this.destroy$))
      .subscribe(state => {
        this.isVideoPlayerVisible = state;
        this.cdRef.markForCheck();
      });

    this.router.events.pipe(filter(event => event instanceof NavigationEnd)).subscribe((event: NavigationEnd) => {
      this.showBanners = this.shouldShowBanners(event.url);
      this.checkUrl(event.url);
    });
    this.shouldShowBanners(this.router.url);

    this.checkUrl(this.router.routerState.snapshot.url);
  }

  checkUrl(url: string) {
    url === '/horseracing/about' ? (this.isAboutPage = true) : (this.isAboutPage = false);
    this.cdRef.markForCheck();
  }

  shouldShowBanners(url: string): boolean {
    let urlOfPage = url.split('/');
    let lastUrlOfPage = urlOfPage[urlOfPage.length - 1];

    return lastUrlOfPage === 'meetings' || lastUrlOfPage === 'horseracing' || !urlOfPage.includes('about')
      ? (this.showBanners = true)
      : (this.showBanners = false);
  }

  ngOnDestroy(): void {
    this.destroy$.next(true);
    this.destroy$.unsubscribe();
  }

  showVideoPlayer(): void {
    if (this.warnOnDataConsumption) {
      this.messageService
        .sendComponentMessage(
          WarningDataComponent,
          {
            messageKey: 'WARN.DATA.STREAMING'
          },
          { queue: true },
          this.destroy$,
          true
        )
        .closed.subscribe(result => {
          if (!result) {
            return;
          }
          this.show();
        });
    } else {
      this.show();
    }
  }

  show() {
    this.isVideoPlayerVisible = !this.isVideoPlayerVisible;
    this.dialogService.toggleDialog('horseracing-livestream', this.isVideoPlayerVisible);
  }

  closeVideoPlayer(): void {
    this.isVideoPlayerVisible = false;
    this.dialogService.toggleDialog('horseracing-livestream', false);
  }
}
