import { Component, ChangeDetectionStrategy, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { DestroySubject, getDateInBrowserTimeZone } from '@honoregaming/core';
import { takeUntil } from 'rxjs/operators';
import { EventsService } from '@honoregaming/events';

@Component({
  selector: 'hg-horseracing-next-quinte-plus',
  templateUrl: './next-quinte-plus.component.html',
  styleUrls: ['./next-quinte-plus.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class NextQuintePlusComponent extends DestroySubject implements OnInit {
  constructor(private eventsService: EventsService, private router: Router) {
    super();
  }

  ngOnInit() {
    this.eventsService
      .getNextQuinte(false, getDateInBrowserTimeZone())
      .pipe(takeUntil(this.destroy$))
      .subscribe(nextQuinte => {
        if (nextQuinte) {
          this.router.navigate(['/horseracing/race', 'R' + nextQuinte.meeting.number + 'C' + nextQuinte.number], {
            queryParams: {
              betTypeId: 14,
              date: new Date(nextQuinte.expectedStart).toISOString().slice(0, 10)
            },
            skipLocationChange: true
          });
        } else {
          this.router.navigate(['/horseracing']);
        }
      });
  }
}
