import { Directive, ChangeDetectorRef, Inject, OnDestroy, OnInit } from '@angular/core';
import { EnabledDisabledMode, operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';
import { DestroySubject, DialogService } from '@honoregaming/core';
import { MenuCustomizationService, HorseRacingMenuLink } from '@honoregaming/customer-core';
import { MessageService, WarningDataComponent } from '@honoregaming/ui';
import { takeUntil } from 'rxjs/operators';

// used for retro compat
const OLD_HORSE_MENU_CONFIGURATION: HorseRacingMenuLink[] = [
  {
    id: 'NextDepartures',
    action: { url: '/horseracing' },
    iconUrl: 'hg-horse-head',
    text: 'MENU.HORSERACING.NEXT_RACES'
  },
  {
    id: 'France',
    action: { url: '/horseracing/meetings' },
    iconUrl: 'hghr-horseracing-pmu',
    text: 'MENU.HORSERACING.FRANCE'
  },
  {
    id: 'Results',
    requiresFeature: 'results',
    action: { url: '/horseracing/results' },
    iconUrl: 'hg-result',
    text: 'MENU.HORSERACING.RESULTS'
  },
  {
    id: 'Programs',
    requiresFeature: 'coupons',
    action: { url: '/horseracing/program' },
    iconUrl: 'hg-result',
    text: 'MENU.HORSERACING.PROGRAM'
  },
  { id: 'HowToBet', action: { url: '/horseracing/about' }, iconUrl: 'hg-help', text: 'MENU.HORSERACING.HOWTOBET' },
  {
    id: 'LiveTV',
    requiresFeature: 'streaming',
    action: { dialog: 'horseracing-livestream' },
    iconUrl: 'hg-tv',
    text: 'MENU.HORSERACING.LIVETV'
  }
];

@Directive()
export abstract class HorseRacingMenuBaseComponent extends DestroySubject implements OnInit, OnDestroy {
  public isStreamingAvailable: boolean =
    this.operatorConfiguration.features.horseRacingFeatures.streamingMode === EnabledDisabledMode.Enabled;
  public isVideoPlayerVisible: boolean;
  public links: HorseRacingMenuLink[] = [];

  warnDataConsumption = this.operatorConfiguration.onlineConfiguration?.warnOnDataConsumption;

  constructor(
    private cdRef: ChangeDetectorRef,
    private dialogService: DialogService,
    private messageService: MessageService,
    private menuCustomizationService: MenuCustomizationService,
    @Inject(operatorConfigurationToken) public operatorConfiguration: OperatorConfiguration
  ) {
    super();
    this.links = this.menuCustomizationService.getHorseRacingMenuLinks(OLD_HORSE_MENU_CONFIGURATION);
  }

  ngOnInit() {
    this.dialogService
      .registerDialog('horseracing-livestream')
      .pipe(takeUntil(this.destroy$))
      .subscribe(state => {
        this.isVideoPlayerVisible = state;
        this.cdRef.markForCheck();
      });
  }

  ngOnDestroy(): void {
    this.destroy$.next(true);
    this.destroy$.unsubscribe();
  }

  showVideoPlayer(): void {
    if (this.warnDataConsumption) {
      this.messageService
        .sendComponentMessage(
          WarningDataComponent,
          {
            messageKey: 'WARN.DATA.STREAMING'
          },
          { queue: true },
          this.destroy$,
          true
        )
        .closed.subscribe(result => {
          if (!result) {
            return;
          }
          this.show();
        });
    } else {
      this.show();
    }
  }

  show() {
    this.isVideoPlayerVisible = !this.isVideoPlayerVisible;
    this.dialogService.toggleDialog('horseracing-livestream', this.isVideoPlayerVisible);

    this.cdRef.markForCheck();
  }

  closeVideoPlayer(): void {
    this.isVideoPlayerVisible = false;
    this.dialogService.toggleDialog('horseracing-livestream', false);
  }
}
