import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  Input,
  Output,
  EventEmitter,
  ChangeDetectorRef,
  ViewChild,
  ViewContainerRef,
  Inject,
  PLATFORM_ID,
  ElementRef,
  HostListener
} from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { HorseRace, HorseRaceMeeting, HorseRaceStateType } from '@honoregaming/types';

@Component({
  selector: 'hg-horseracing-race-selector',
  templateUrl: './race-selector.component.html',
  styleUrls: ['./race-selector.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class RaceSelectorComponent implements OnInit {
  @Input()
  racesPerMeetings: {
    meeting: HorseRaceMeeting;
    races: HorseRace[];
  }[];

  @Input()
  currentMeetingNumber: number;

  @Input()
  date: string;

  @Input()
  currentRaceNumber: number;

  opened = false;

  @Output()
  raceChanged = new EventEmitter<{ meetingNumber: number; raceNumber: number; date: string }>();

  @ViewChild('races', { read: ViewContainerRef, static: true })
  races: ViewContainerRef;

  currentMeetingWithRaces: {
    meeting: HorseRaceMeeting;
    races: HorseRace[];
  };
  HorseRaceStateType = HorseRaceStateType;

  currentRace: HorseRace;

  constructor(private cdRef: ChangeDetectorRef, @Inject(PLATFORM_ID) private platId) {}

  ngOnInit() {
    this.currentMeetingWithRaces = this.racesPerMeetings.find(x => x.meeting.number === this.currentMeetingNumber);
    this.currentRace = this.currentMeetingWithRaces.races.find(x => x.number === this.currentRaceNumber);
    if (isPlatformBrowser(this.platId)) {
      setTimeout(() => {
        const parentElement = this.races.element.nativeElement as HTMLElement;
        const activeElement = parentElement.querySelector('.selected') as HTMLElement;
        parentElement.scrollBy?.({
          behavior: 'smooth',
          left: activeElement.getClientRects().item(0).left - 85
        });
      });
    }
  }

  changeCurrentMeeting(meetingNumber: number) {
    this.currentMeetingWithRaces = this.racesPerMeetings.find(x => x.meeting.number === meetingNumber);
    this.changeCurrentRace(this.currentMeetingWithRaces.races[0]);
    this.cdRef.markForCheck();
  }

  changeCurrentRace(race: HorseRace) {
    this.opened = false;
    this.currentRace = race;
    this.raceChanged.emit({
      meetingNumber: this.currentMeetingWithRaces.meeting.number,
      raceNumber: this.currentRace.number,
      date: this.date
    });

    this.cdRef.markForCheck();
  }

  @ViewChild('sideNav') sideNav: ElementRef;
  @HostListener('document:click', ['$event'])
  outsideClick(event: any): void {
    if (!this.sideNav.nativeElement.contains(event.target)) {
      this.opened = false;
    }
  }

  toggleMeetingsSelector() {
    this.opened = !this.opened;
  }
}
