import { Component, ChangeDetectionStrategy, Input, OnInit } from '@angular/core';
import { DestroySubject } from '@honoregaming/core';
import { HorseracingAboutService } from '../../about/services/horseracing-about.service';
import { finalize, takeUntil } from 'rxjs/operators';
import { HowToBetTypesGuide } from '../../about/models/howto-bettypes-guide.model';

@Component({
  selector: 'hg-popin-bettypes-informations',
  templateUrl: './popin-bettypes-informations.component.html',
  styleUrls: ['./popin-bettypes-informations.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class PopinBettypesInformationsComponent extends DestroySubject implements OnInit {
  @Input()
  betTypes: { id: string; booster: boolean }[];

  @Input()
  iconUrl: string;

  @Input()
  currentBetTypeId: string;

  isLoading = false;
  imgUrl: string = null;
  content: HowToBetTypesGuide;

  constructor(private horseracingAboutService: HorseracingAboutService) {
    super();
  }

  ngOnInit() {
    this.isLoading = true;
    this.horseracingAboutService
      .getHorseRacingHowToContent()
      .pipe(
        finalize(() => (this.isLoading = false)),
        takeUntil(this.destroy$)
      )
      .subscribe(content => {
        this.content = content.betTypesGuideContents;
      });
  }

  onBetTypeClick(betTypeId: string) {
    this.currentBetTypeId = betTypeId;
  }
}
