import { Component, ChangeDetectionStrategy, Input, HostBinding, ViewEncapsulation } from '@angular/core';

@Component({
  selector: 'hg-tooltip',
  templateUrl: './tooltip.component.html',
  styleUrls: ['./tooltip.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None
})
export class TooltipComponent {
  @HostBinding('class.left')
  get left() {
    return this.orientation === 'left';
  }
  @HostBinding('class.right')
  get right() {
    return this.orientation === 'right';
  }
  @HostBinding('class.top')
  get top() {
    return this.orientation === 'top';
  }
  @HostBinding('class.bottom')
  get bottom() {
    return this.orientation === 'bottom';
  }

  @Input()
  orientation: 'left' | 'right' | 'top' | 'bottom' = 'bottom';

  constructor() {}
}
