import { Component, OnInit, ChangeDetectionStrategy, ChangeDetectorRef, Input } from '@angular/core';
import { DialogService } from '@honoregaming/core';
import { takeUntil } from 'rxjs/operators';
import { DestroySubject } from '@honoregaming/core';

@Component({
  selector: 'hg-horseracing-sidebar',
  templateUrl: './sidebar.component.html',
  styleUrls: ['./sidebar.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SidebarComponent extends DestroySubject implements OnInit {
  betSlipActive = false;
  @Input() hasTableContents: boolean;

  constructor(private dialogService: DialogService, private cdRef: ChangeDetectorRef) {
    super();
  }

  ngOnInit() {
    this.dialogService
      .registerDialog('betslip')
      .pipe(takeUntil(this.destroy$))
      .subscribe(open => {
        this.betSlipActive = open;
        this.cdRef.markForCheck();
      });
  }

  closeBetSlip() {
    this.dialogService.toggleDialog('betslip', false);
  }
}
