import { RouterModule, Routes } from '@angular/router';
import { NgModule } from '@angular/core';
import { RaceDetailComponent } from './containers/race-detail/race-detail.component';
import { SidebarComponent } from './components/sidebar/sidebar.component';
import { LayoutComponent } from './containers/layout/layout.component';
import { NextQuintePlusComponent } from './containers/next-quinte-plus/next-quinte-plus.component';
import { RacesResultsComponent } from './containers/races-results/races-results.component';
import { RacesResultsPdfComponent } from './containers/races-results-pdf/races-results-pdf.component';
import { RacesProgramComponent } from './containers/races-program/races-program.component';
import { RaceResultsDetailsComponent } from './containers/race-results-details/race-results-details.component';
import { NavHeaderComponent } from './components/nav-header/nav-header.component';
import { UpcomingRacesComponent } from './containers/upcoming-races/upcoming-races.component';
import { RacesOfTheNextDaysComponent } from './containers/races-of-the-next-days/races-of-the-next-days.component';

const routes: Routes = [
  {
    path: '',
    component: LayoutComponent,
    children: [
      { path: '', component: UpcomingRacesComponent, data: { 'sidebar-content': 'none' } },
      { path: 'meetings', component: RacesOfTheNextDaysComponent, data: { 'sidebar-content': 'none' } },
      { path: 'results', component: RacesResultsComponent, data: { 'sidebar-content': 'none' } },
      { path: 'results-details/:raceId', component: RaceResultsDetailsComponent, data: { 'sidebar-content': 'none' } },
      { path: 'results-pdf', component: RacesResultsPdfComponent, data: { 'sidebar-content': 'none' } },
      { path: 'program', component: RacesProgramComponent, data: { 'sidebar-content': 'none' } },
      {
        path: 'race/:racePath',
        children: [
          { path: '', component: RaceDetailComponent, data: { 'sidebar-content': 'none' } },
          { path: '', outlet: 'sidebar', component: SidebarComponent }
        ]
      },
      { path: 'quinte', component: NextQuintePlusComponent, data: { 'sidebar-content': 'none' } },
      {
        path: 'about',
        loadChildren: () => import('./about/hg-horseracing-about.module').then(m => m.HgHorseracingAboutModule)
      }
    ]
  },
  { path: '', outlet: 'subheader', component: NavHeaderComponent }
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class HgHorseracingRoutingModule {}
