import { Component, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';

@Component({
  selector: 'hg-horseracing-races-of-the-next-days',
  templateUrl: './races-of-the-next-days.component.html',
  styleUrls: ['./races-of-the-next-days.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class RacesOfTheNextDaysComponent {
  public numberOfMeetingsOfToday: number;
  public numberOfMeetingsOfTomorrow: number;

  constructor(private cdRef: ChangeDetectorRef) {}

  getNumberOfRacesForToday(numberOfMeetings: number) {
    this.numberOfMeetingsOfToday = numberOfMeetings;
    this.cdRef.markForCheck();
  }

  getNumberOfRacesForTomorrow(numberOfMeetings: number) {
    this.numberOfMeetingsOfTomorrow = numberOfMeetings;
    this.cdRef.markForCheck();
  }
}
